open-addressing.pseudocode:
DELETED = object()  # 툼스톤 표시

def search(T, k):
    for i in range(len(T)):
        j = (h(k) + i) % len(T)  # 선형 (이차: i*i)
        if T[j] is None:  # 빈 칸 → 키 없음
            return -1
        if T[j] == k:  # 툼스톤은 건너뛰고 계속 탐사
            return j
    return -1

def insert(T, k):
    if search(T, k) >= 0:
        return  # 이미 존재
    for i in range(len(T)):
        j = (h(k) + i) % len(T)
        if T[j] is None or T[j] is DELETED:
            T[j] = k  # 툼스톤 자리 재사용
            return
    raise OverflowError('table full')  # 재해싱 필요

def delete(T, k):
    j = search(T, k)
    if j >= 0:
        T[j] = DELETED  # None으로 지우면 탐사 체인 끊김

