  PaymentMethod <|.. Card
  PaymentMethod <|.. Kakao
  PaymentMethod <|.. NewPay : 신규 추가 (확장 열림)

open-closed-principle.pseudocode:
# 위반: 새 결제 수단마다 기존 함수 수정
def pay_bad(kind, amount):
    if kind == 'card':
        charge_card(amount)
    elif kind == 'kakao':
        charge_kakao(amount)
    # 신규 수단 → elif 추가 (조건 분기 증가)

# 준수: 추상화 + 다형성
class PaymentMethod:
    def process(self, amount):
        raise NotImplementedError

class Card(PaymentMethod):
    def process(self, amount):
        charge_card(amount)

class NewPay(PaymentMethod):  # 클래스 추가만
    def process(self, amount):
        charge_new(amount)

def pay(method, amount):  # 기존 코드 무수정
    method.process(amount)

optimal-page-replacement.pseudocode:
def opt(refs, capacity):
    frames, faults = [], 0
    for i, page in enumerate(refs):
        if page in frames:
            continue  # 적중
        faults += 1
        if len(frames) < capacity:
            frames.append(page)
            continue

        def next_use(p):  # 다음 참조 위치(없으면 무한대)
            for j in range(i + 1, len(refs)):
                if refs[j] == p:
                    return j
            return float('inf')

        victim = max(frames, key=next_use)  # 가장 늦게 쓰일
        frames[frames.index(victim)] = page
    return faults
